name: Build

on:
  workflow_call:
    inputs:
      duckdb_version:
        description: DuckDB version to build; omitted when the extension repository pins a DuckDB submodule
        required: false
        type: string
        default: ""
      duckdb_commit:
        description: Exact DuckDB commit to build; omitted when the extension repository pins a DuckDB submodule
        required: false
        type: string
        default: ""
      ci_tools_version:
        description: extension-ci-tools ref used by build and test jobs
        required: false
        type: string
        default: main
      groups:
        description: YAML extension groups passed to duckdb-ci/matrix
        required: true
        type: string
      extension_repository:
        description: Extension repository override
        required: false
        type: string
        default: ""
      extension_ref:
        description: Extension repository ref override
        required: false
        type: string
        default: ""
      duckdb_repository:
        description: DuckDB repository override used by the extension Makefile
        required: false
        type: string
        default: ""
      ci_tools_repository:
        description: Repository containing extension-ci-tools
        required: false
        type: string
        default: duckdb/extension-ci-tools
      exclude_archs:
        description: Semicolon-separated architectures to exclude
        required: false
        type: string
        default: ""
      opt_in_archs:
        description: Semicolon-separated opt-in architectures; opt-ins override reduced CI, while exclusions take precedence
        required: false
        type: string
        default: ""
      allow_failure_archs:
        description: Semicolon-separated architectures that should not fail the workflow
        required: false
        type: string
        default: ""
      runners:
        description: JSON runner overrides accepted by duckdb-ci/matrix
        required: false
        type: string
        default: "{}"
      reduced_ci_mode:
        description: Reduced CI mode (auto, enabled, or disabled)
        required: false
        type: string
        default: auto
      image_version:
        description: duckdb-ci container image version
        required: false
        type: string
        default: 20260814-e87a46ea
      skip_tests:
        description: Skip tests
        required: false
        type: boolean
        default: false
      save_cache:
        description: Save ccache after the build
        required: false
        type: boolean
        default: true
      prebuilt_source:
        description: Prebuilt DuckDB source (workflow, staged, or disabled); defaults to staged unless a legacy artifact is provided
        required: false
        type: string
        default: ""
      prebuilt_duckdb:
        description: Deprecated JSON map from DuckDB architecture to same-run artifact name
        required: false
        type: string
        default: "{}"
      vcpkg_url:
        description: vcpkg repository
        required: false
        type: string
        default: https://github.com/microsoft/vcpkg.git
      vcpkg_commit:
        description: vcpkg commit
        required: false
        type: string
        default: cd61e1e26a038e82d6550a3ebbe0fbbfe7da78e3 # Release 2026.06.24
      windows_vcpkg_toolchain:
        description: Windows compiler and matching vcpkg toolchain (cl or clang-cl)
        required: false
        type: string
        default: cl
    secrets:
      VCPKG_CACHING_AWS_ACCESS_KEY_ID:
        required: false
      VCPKG_CACHING_AWS_SECRET_ACCESS_KEY:
        required: false
      VCPKG_CACHING_AWS_ENDPOINT_URL:
        required: false
      VCPKG_CACHING_AWS_DEFAULT_REGION:
        required: false
    outputs:
      duckdb_version:
        description: Resolved DuckDB version used by the build
        value: ${{ jobs.matrix.outputs.duckdb_version }}
      duckdb_commit:
        description: Resolved DuckDB commit used by the build
        value: ${{ jobs.matrix.outputs.duckdb_commit }}

permissions:
  contents: read
  packages: read

env:
  CI_BUILD_TYPE: release
  CI_BUILD_DUCKDB_SHELL: true
  CI_UPLOAD_ALL_EXTENSIONS: true
  CI_SKIP_TESTS: ${{ inputs.skip_tests }}
  CI_EXTENSIONS_TEST_SELECTION: complete
  CI_VCPKG_URL: ${{ inputs.vcpkg_url }}
  CI_VCPKG_COMMIT: ${{ inputs.vcpkg_commit }}
  CI_VCPKG_OVERLAY_PORTS: extension-ci-tools/vcpkg_ports
  CI_VCPKG_OVERLAY_TRIPLETS: extension-ci-tools/toolchains
  CI_CUDA_VERSION: 13
  VCPKG_BINARY_SOURCES: clear;http,https://vcpkg-cache.duckdb.org,read
  AWS_REQUEST_CHECKSUM_CALCULATION: when_required
  GEN: ninja

jobs:
  matrix:
    name: Compute matrix
    runs-on: ${{ fromJSON(inputs.runners).linux_slim || 'ubuntu-slim' }}
    outputs:
      duckdb_version: ${{ steps.duckdb-version.outputs.version }}
      duckdb_commit: ${{ steps.duckdb-version.outputs.commit }}
      build_linux: ${{ steps.matrix.outputs.build_linux }}
      test_linux: ${{ steps.matrix.outputs.test_linux }}
      build_macos: ${{ steps.matrix.outputs.build_macos }}
      test_macos: ${{ steps.matrix.outputs.test_macos }}
      build_windows: ${{ steps.matrix.outputs.build_windows }}
      test_windows: ${{ steps.matrix.outputs.test_windows }}
      build_wasm: ${{ steps.matrix.outputs.build_wasm }}
    steps:
      - name: Checkout extension metadata
        if: ${{ inputs.duckdb_version == '' && inputs.duckdb_commit == '' }}
        uses: actions/checkout@9c091bb21b7c1c1d1991bb908d89e4e9dddfe3e0 # v7.0.0
        with:
          repository: ${{ inputs.extension_repository != '' && inputs.extension_repository || github.repository }}
          ref: ${{ inputs.extension_ref }}
          fetch-depth: 0
      - name: Resolve DuckDB version
        id: duckdb-version
        shell: bash
        env:
          INPUT_DUCKDB_VERSION: ${{ inputs.duckdb_version }}
          INPUT_DUCKDB_COMMIT: ${{ inputs.duckdb_commit }}
        run: |
          set -euo pipefail
          duckdb_commit="${INPUT_DUCKDB_COMMIT:-${INPUT_DUCKDB_VERSION}}"
          duckdb_version="${INPUT_DUCKDB_VERSION:-${duckdb_commit}}"
          if [[ -z "${duckdb_commit}" ]]; then
            if ! duckdb_commit="$(git rev-parse HEAD:duckdb 2>/dev/null)"; then
              echo "duckdb_version or duckdb_commit is required when the extension repository has no duckdb submodule" >&2
              exit 1
            fi
            duckdb_version="${duckdb_commit}"
          fi
          echo "version=${duckdb_version}" >> "$GITHUB_OUTPUT"
          echo "commit=${duckdb_commit}" >> "$GITHUB_OUTPUT"
      - name: Compute matrix
        id: matrix
        uses: duckdb/duckdb-ci/matrix@46370d44f2162edd523c8e0d35902967c2817152 # main
        with:
          exclude_archs: ${{ inputs.exclude_archs }}
          opt_in_archs: ${{ inputs.opt_in_archs }}
          runners: ${{ inputs.runners }}
          reduced_ci_mode: ${{ inputs.reduced_ci_mode }}
          image_version: ${{ inputs.image_version }}
          windows_vcpkg_toolchain: ${{ inputs.windows_vcpkg_toolchain }}
          groups: ${{ inputs.groups }}

  build_linux:
    name: Build Linux (${{ matrix.group_name }}, ${{ matrix.duckdb_arch }})
    continue-on-error: ${{ contains(format(';{0};', inputs.allow_failure_archs), format(';{0};', matrix.duckdb_arch)) }}
    needs: matrix
    if: ${{ needs.matrix.outputs.build_linux != '' && needs.matrix.outputs.build_linux != '{"include":[]}' }}
    runs-on: ${{ matrix.runner }}
    container:
      image: ${{ matrix.container }}
      credentials:
        username: ${{ github.actor }}
        password: ${{ secrets.GITHUB_TOKEN }}
    strategy:
      fail-fast: false
      matrix: ${{ fromJSON(needs.matrix.outputs.build_linux) }}
    env:
      DUCKDB_VERSION: ${{ needs.matrix.outputs.duckdb_version }}
      DUCKDB_COMMIT: ${{ needs.matrix.outputs.duckdb_commit }}
      CI_PLATFORM: linux
      CI_LINUX_NATIVE_CONTAINER: true
      DUCKDB_PLATFORM: ${{ matrix.duckdb_arch }}
      CI_EXTENSION_NAME: ${{ matrix.artifact_prefix }}
      CI_ARTIFACT_NAME: ${{ matrix.artifact_name }}
      CI_EXTENSION_CONFIG_PATHS: ${{ toJSON(matrix.extension_config_paths) }}
      CI_EXTRA_TOOLCHAINS: ${{ format('{0};{1}', matrix.toolchain, matrix.extra_toolchains) }}
      CI_HAS_RUST: ${{ matrix.toolchain == 'rust' }}
      VCPKG_TARGET_TRIPLET: ${{ matrix.vcpkg_target_triplet }}
      VCPKG_HOST_TRIPLET: ${{ matrix.vcpkg_host_triplet }}
      AWS_ACCESS_KEY_ID: ${{ secrets.VCPKG_CACHING_AWS_ACCESS_KEY_ID }}
      AWS_SECRET_ACCESS_KEY: ${{ secrets.VCPKG_CACHING_AWS_SECRET_ACCESS_KEY }}
      AWS_ENDPOINT_URL: ${{ secrets.VCPKG_CACHING_AWS_ENDPOINT_URL }}
      AWS_DEFAULT_REGION: ${{ secrets.VCPKG_CACHING_AWS_DEFAULT_REGION }}
      CI_PREBUILT_DUCKDB_SOURCE: ${{ inputs.prebuilt_source || (fromJSON(inputs.prebuilt_duckdb)[matrix.duckdb_arch] && 'workflow') || 'staged' }}
      CI_PREBUILT_DUCKDB_ARTIFACT: ${{ fromJSON(inputs.prebuilt_duckdb)[matrix.duckdb_arch] || matrix.prebuilt_duckdb_artifact }}
      CI_PREBUILT_DUCKDB_PATH: ${{ github.workspace }}/.ci/prebuilt-duckdb/${{ matrix.duckdb_arch }}
    steps:
      - name: Prepare sources
        uses: &duckdb-ci-prepare-extension duckdb/duckdb-ci/prepare-extension@46370d44f2162edd523c8e0d35902967c2817152 # main
        with:
          extension-repository: ${{ inputs.extension_repository != '' && inputs.extension_repository || github.repository }}
          extension-ref: ${{ inputs.extension_ref }}
          duckdb-repository: ${{ inputs.duckdb_repository }}
          duckdb-ref: ${{ needs.matrix.outputs.duckdb_commit }}
          duckdb-sha: ${{ needs.matrix.outputs.duckdb_commit }}
      - name: Checkout extension-ci-tools
        uses: actions/checkout@9c091bb21b7c1c1d1991bb908d89e4e9dddfe3e0 # v7.0.0
        with:
          path: extension-ci-tools
          repository: ${{ inputs.ci_tools_repository }}
          ref: ${{ inputs.ci_tools_version }}
      - name: Download prebuilt DuckDB
        if: ${{ env.CI_PREBUILT_DUCKDB_SOURCE == 'workflow' && env.CI_PREBUILT_DUCKDB_ARTIFACT != '' }}
        uses: actions/download-artifact@70fc10c6e5e1ce46ad2ea6f2b72d43f7d47b13c3 # v8.0.0
        with:
          name: ${{ env.CI_PREBUILT_DUCKDB_ARTIFACT }}
          path: ${{ env.CI_PREBUILT_DUCKDB_PATH }}
      - name: Setup ccache
        uses: hendrikmuhs/ccache-action@d62db5f07c26379fc4b4e0916f098a92573c3b03 # v1.2.23
        continue-on-error: true
        with:
          max-size: 5GB
          evict-old-files: job
          key: build-${{ matrix.artifact_name }}-${{ needs.matrix.outputs.duckdb_version }}
          restore-keys: |
            ccache-build-${{ matrix.artifact_name }}-${{ needs.matrix.outputs.duckdb_version }}
            build-${{ matrix.artifact_name }}-
            ccache-build-${{ matrix.artifact_name }}-
          save: ${{ inputs.save_cache }}
      - name: Configure
        run: python3 extension-ci-tools/scripts/ci_phase.py setup
      - name: Build
        uses: &duckdb-ci-build-duckdb duckdb/duckdb-ci/build-duckdb@46370d44f2162edd523c8e0d35902967c2817152 # main
        with:
          build: python3 extension-ci-tools/scripts/ci_phase.py build
          test: python3 extension-ci-tools/scripts/ci_phase.py test
          vcpkg-commit: ${{ inputs.vcpkg_commit }}
          save-cache: ${{ inputs.save_cache }}
          cache-suffix: ${{ matrix.group_name }}-${{ matrix.container_name || matrix.duckdb_arch }}
      - name: Prepare extension artifact
        id: artifact
        run: python3 extension-ci-tools/scripts/ci_phase.py upload
      - name: Upload extension artifact
        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
        with:
          name: ${{ steps.artifact.outputs.artifact_name }}
          path: ${{ steps.artifact.outputs.artifact_path }}
          if-no-files-found: error

  build_macos:
    name: Build macOS (${{ matrix.group_name }}, ${{ matrix.duckdb_arch }})
    continue-on-error: ${{ contains(format(';{0};', inputs.allow_failure_archs), format(';{0};', matrix.duckdb_arch)) }}
    needs: matrix
    if: ${{ needs.matrix.outputs.build_macos != '' }}
    runs-on: ${{ matrix.runner }}
    strategy:
      fail-fast: false
      matrix: ${{ fromJSON(needs.matrix.outputs.build_macos) }}
    env:
      DUCKDB_VERSION: ${{ needs.matrix.outputs.duckdb_version }}
      DUCKDB_COMMIT: ${{ needs.matrix.outputs.duckdb_commit }}
      CI_PLATFORM: macos
      DUCKDB_PLATFORM: ${{ matrix.duckdb_arch }}
      CI_OSX_BUILD_ARCH: ${{ matrix.osx_build_arch }}
      OSX_BUILD_ARCH: ${{ matrix.osx_build_arch }}
      CI_EXTENSION_NAME: ${{ matrix.artifact_prefix }}
      CI_ARTIFACT_NAME: ${{ matrix.artifact_name }}
      CI_EXTENSION_CONFIG_PATHS: ${{ toJSON(matrix.extension_config_paths) }}
      CI_EXTRA_TOOLCHAINS: ${{ format('{0};{1}', matrix.toolchain, matrix.extra_toolchains) }}
      CI_HAS_RUST: ${{ matrix.toolchain == 'rust' }}
      VCPKG_TARGET_TRIPLET: ${{ matrix.vcpkg_target_triplet }}
      VCPKG_HOST_TRIPLET: ${{ matrix.vcpkg_host_triplet }}
      AWS_ACCESS_KEY_ID: ${{ secrets.VCPKG_CACHING_AWS_ACCESS_KEY_ID }}
      AWS_SECRET_ACCESS_KEY: ${{ secrets.VCPKG_CACHING_AWS_SECRET_ACCESS_KEY }}
      AWS_ENDPOINT_URL: ${{ secrets.VCPKG_CACHING_AWS_ENDPOINT_URL }}
      AWS_DEFAULT_REGION: ${{ secrets.VCPKG_CACHING_AWS_DEFAULT_REGION }}
      CI_PREBUILT_DUCKDB_SOURCE: ${{ inputs.prebuilt_source || (fromJSON(inputs.prebuilt_duckdb)[matrix.duckdb_arch] && 'workflow') || 'staged' }}
      CI_PREBUILT_DUCKDB_ARTIFACT: ${{ fromJSON(inputs.prebuilt_duckdb)[matrix.duckdb_arch] || matrix.prebuilt_duckdb_artifact }}
      CI_PREBUILT_DUCKDB_PATH: ${{ github.workspace }}/.ci/prebuilt-duckdb/${{ matrix.duckdb_arch }}
    steps:
      - name: Prepare sources
        uses: *duckdb-ci-prepare-extension
        with:
          extension-repository: ${{ inputs.extension_repository != '' && inputs.extension_repository || github.repository }}
          extension-ref: ${{ inputs.extension_ref }}
          duckdb-repository: ${{ inputs.duckdb_repository != '' && inputs.duckdb_repository || 'duckdb/duckdb' }}
          duckdb-ref: ${{ needs.matrix.outputs.duckdb_commit }}
          duckdb-sha: ${{ needs.matrix.outputs.duckdb_commit }}
      - name: Checkout extension-ci-tools
        uses: actions/checkout@9c091bb21b7c1c1d1991bb908d89e4e9dddfe3e0 # v7.0.0
        with:
          path: extension-ci-tools
          repository: ${{ inputs.ci_tools_repository }}
          ref: ${{ inputs.ci_tools_version }}
      - name: Download prebuilt DuckDB
        if: ${{ env.CI_PREBUILT_DUCKDB_SOURCE == 'workflow' && env.CI_PREBUILT_DUCKDB_ARTIFACT != '' }}
        uses: actions/download-artifact@70fc10c6e5e1ce46ad2ea6f2b72d43f7d47b13c3 # v8.0.0
        with:
          name: ${{ env.CI_PREBUILT_DUCKDB_ARTIFACT }}
          path: ${{ env.CI_PREBUILT_DUCKDB_PATH }}
      - name: Setup Python
        uses: actions/setup-python@ece7cb06caefa5fff74198d8649806c4678c61a1 # v6.3.0
        with:
          python-version: "3.11"
      - name: Setup Rust
        if: ${{ matrix.toolchain == 'rust' }}
        uses: dtolnay/rust-toolchain@4cda84d5c5c54efe2404f9d843567869ab1699d4 # stable
      - name: Setup ccache
        uses: hendrikmuhs/ccache-action@d62db5f07c26379fc4b4e0916f098a92573c3b03 # v1.2.23
        continue-on-error: true
        with:
          max-size: 5GB
          evict-old-files: job
          key: build-${{ matrix.artifact_name }}-${{ needs.matrix.outputs.duckdb_version }}
          restore-keys: |
            ccache-build-${{ matrix.artifact_name }}-${{ needs.matrix.outputs.duckdb_version }}
            build-${{ matrix.artifact_name }}-
            ccache-build-${{ matrix.artifact_name }}-
          save: ${{ inputs.save_cache }}
      - name: Configure
        run: python3 extension-ci-tools/scripts/ci_phase.py setup
      - name: Build
        uses: *duckdb-ci-build-duckdb
        with:
          build: python3 extension-ci-tools/scripts/ci_phase.py build
          test: python3 extension-ci-tools/scripts/ci_phase.py test
          vcpkg-commit: ${{ inputs.vcpkg_commit }}
          save-cache: ${{ inputs.save_cache }}
          cache-suffix: ${{ matrix.group_name }}-${{ matrix.container_name || matrix.duckdb_arch }}
      - name: Prepare extension artifact
        id: artifact
        run: python3 extension-ci-tools/scripts/ci_phase.py upload
      - name: Upload extension artifact
        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
        with:
          name: ${{ steps.artifact.outputs.artifact_name }}
          path: ${{ steps.artifact.outputs.artifact_path }}
          if-no-files-found: error

  build_windows:
    name: Build Windows (${{ matrix.group_name }}, ${{ matrix.duckdb_arch }})
    continue-on-error: ${{ contains(format(';{0};', inputs.allow_failure_archs), format(';{0};', matrix.duckdb_arch)) }}
    needs: matrix
    if: ${{ needs.matrix.outputs.build_windows != '' }}
    runs-on: ${{ matrix.runner }}
    strategy:
      fail-fast: false
      matrix: ${{ fromJSON(needs.matrix.outputs.build_windows) }}
    env:
      DUCKDB_VERSION: ${{ needs.matrix.outputs.duckdb_version }}
      DUCKDB_COMMIT: ${{ needs.matrix.outputs.duckdb_commit }}
      CI_PLATFORM: windows
      DUCKDB_PLATFORM: ${{ matrix.duckdb_arch }}
      CI_EXTENSION_NAME: ${{ matrix.artifact_prefix }}
      CI_ARTIFACT_NAME: ${{ matrix.artifact_name }}
      CI_EXTENSION_CONFIG_PATHS: ${{ toJSON(matrix.extension_config_paths) }}
      CI_EXTRA_TOOLCHAINS: ${{ format('{0};{1}', matrix.toolchain, matrix.extra_toolchains) }}
      CI_HAS_RUST: ${{ matrix.toolchain == 'rust' }}
      VCPKG_TARGET_TRIPLET: ${{ matrix.vcpkg_target_triplet }}
      VCPKG_HOST_TRIPLET: ${{ matrix.vcpkg_host_triplet }}
      VCPKG_OVERLAY_TRIPLETS: ${{ github.workspace }}/extension-ci-tools/toolchains
      AWS_ACCESS_KEY_ID: ${{ secrets.VCPKG_CACHING_AWS_ACCESS_KEY_ID }}
      AWS_SECRET_ACCESS_KEY: ${{ secrets.VCPKG_CACHING_AWS_SECRET_ACCESS_KEY }}
      AWS_ENDPOINT_URL: ${{ secrets.VCPKG_CACHING_AWS_ENDPOINT_URL }}
      AWS_DEFAULT_REGION: ${{ secrets.VCPKG_CACHING_AWS_DEFAULT_REGION }}
      CI_PREBUILT_DUCKDB_SOURCE: ${{ inputs.prebuilt_source || (fromJSON(inputs.prebuilt_duckdb)[matrix.duckdb_arch] && 'workflow') || 'staged' }}
      CI_PREBUILT_DUCKDB_ARTIFACT: ${{ fromJSON(inputs.prebuilt_duckdb)[matrix.duckdb_arch] || matrix.prebuilt_duckdb_artifact }}
      CI_PREBUILT_DUCKDB_PATH: ${{ github.workspace }}/.ci/prebuilt-duckdb/${{ matrix.duckdb_arch }}
      CC: ${{ (matrix.duckdb_arch == 'windows_amd64_rtools' || matrix.duckdb_arch == 'windows_amd64_mingw') && 'gcc' || inputs.windows_vcpkg_toolchain }}
      CXX: ${{ (matrix.duckdb_arch == 'windows_amd64_rtools' || matrix.duckdb_arch == 'windows_amd64_mingw') && 'g++' || inputs.windows_vcpkg_toolchain }}
    steps:
      - name: Configure line endings
        shell: bash
        run: |
          git config --global core.autocrlf false
          git config --global core.eol lf
      - name: Prepare sources
        uses: *duckdb-ci-prepare-extension
        with:
          extension-repository: ${{ inputs.extension_repository != '' && inputs.extension_repository || github.repository }}
          extension-ref: ${{ inputs.extension_ref }}
          duckdb-repository: ${{ inputs.duckdb_repository != '' && inputs.duckdb_repository || 'duckdb/duckdb' }}
          duckdb-ref: ${{ needs.matrix.outputs.duckdb_commit }}
          duckdb-sha: ${{ needs.matrix.outputs.duckdb_commit }}
      - name: Checkout extension-ci-tools
        uses: actions/checkout@9c091bb21b7c1c1d1991bb908d89e4e9dddfe3e0 # v7.0.0
        with:
          path: extension-ci-tools
          repository: ${{ inputs.ci_tools_repository }}
          ref: ${{ inputs.ci_tools_version }}
      - name: Download prebuilt DuckDB
        if: ${{ env.CI_PREBUILT_DUCKDB_SOURCE == 'workflow' && env.CI_PREBUILT_DUCKDB_ARTIFACT != '' }}
        uses: actions/download-artifact@70fc10c6e5e1ce46ad2ea6f2b72d43f7d47b13c3 # v8.0.0
        with:
          name: ${{ env.CI_PREBUILT_DUCKDB_ARTIFACT }}
          path: ${{ env.CI_PREBUILT_DUCKDB_PATH }}
      - name: Setup Python
        uses: actions/setup-python@ece7cb06caefa5fff74198d8649806c4678c61a1 # v6.3.0
        with:
          python-version: "3.11"
      - name: Setup Rust
        if: ${{ matrix.toolchain == 'rust' }}
        uses: dtolnay/rust-toolchain@4cda84d5c5c54efe2404f9d843567869ab1699d4 # stable
      - name: Setup Rust for MinGW
        if: ${{ matrix.toolchain == 'rust' && (matrix.duckdb_arch == 'windows_amd64_rtools' || matrix.duckdb_arch == 'windows_amd64_mingw') }}
        uses: dtolnay/rust-toolchain@4cda84d5c5c54efe2404f9d843567869ab1699d4 # stable
        with:
          targets: x86_64-pc-windows-gnu
      - name: Setup ccache
        uses: hendrikmuhs/ccache-action@d62db5f07c26379fc4b4e0916f098a92573c3b03 # v1.2.23
        with:
          max-size: 5GB
          evict-old-files: job
          key: build-${{ matrix.artifact_name }}-${{ needs.matrix.outputs.duckdb_version }}
          restore-keys: |
            ccache-build-${{ matrix.artifact_name }}-${{ needs.matrix.outputs.duckdb_version }}
            build-${{ matrix.artifact_name }}-
            ccache-build-${{ matrix.artifact_name }}-
          save: ${{ inputs.save_cache }}
      - name: Setup Rtools
        if: ${{ matrix.duckdb_arch == 'windows_amd64_rtools' || matrix.duckdb_arch == 'windows_amd64_mingw' }}
        uses: r-lib/actions/setup-r@d3c5be51b12e724e68f33216ca3c148b66d5f0b6 # v2.12.1
        with:
          r-version: devel
          update-rtools: true
          rtools-version: "42"
      - name: Configure short vcpkg path
        shell: pwsh
        run: |
          $basePath = Split-Path -Path (Split-Path -Path $env:GITHUB_WORKSPACE -Parent) -Parent
          $vcpkgRoot = "$basePath/vcpkg"
          "VCPKG_WINDOWS_ROOT=$vcpkgRoot" >> $env:GITHUB_ENV
          "VCPKG_ROOT=$vcpkgRoot" >> $env:GITHUB_ENV
          "VCPKG_TOOLCHAIN_PATH=$vcpkgRoot/scripts/buildsystems/vcpkg.cmake" >> $env:GITHUB_ENV
      - name: Setup vcpkg
        uses: lukka/run-vcpkg@b1a0dd252f06b9e25b3c022a9a03bd7a427fb6a2 # v11.6
        with:
          vcpkgGitCommitId: ${{ inputs.vcpkg_commit }}
          vcpkgGitURL: ${{ inputs.vcpkg_url }}
          vcpkgDirectory: ${{ env.VCPKG_WINDOWS_ROOT }}
      - name: Configure
        run: python extension-ci-tools/scripts/ci_phase.py setup
      - name: Build
        uses: *duckdb-ci-build-duckdb
        with:
          build: python extension-ci-tools/scripts/ci_phase.py build
          test: python extension-ci-tools/scripts/ci_phase.py test
          vcpkg-commit: ${{ inputs.vcpkg_commit }}
          save-cache: ${{ inputs.save_cache }}
          cache-suffix: ${{ matrix.group_name }}-${{ matrix.container_name || matrix.duckdb_arch }}
      - name: Prepare extension artifact
        id: artifact
        run: python extension-ci-tools/scripts/ci_phase.py upload
      - name: Upload extension artifact
        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
        with:
          name: ${{ steps.artifact.outputs.artifact_name }}
          path: ${{ steps.artifact.outputs.artifact_path }}
          if-no-files-found: error

  build_wasm:
