            "AWS_SECRET_ACCESS_KEY": self.value("AWS_SECRET_ACCESS_KEY"),
            "AWS_ENDPOINT_URL": self.value("AWS_ENDPOINT_URL"),
            "AWS_DEFAULT_REGION": self.value("AWS_DEFAULT_REGION"),
